pub(crate) async fn to_bytes<T>(body: T) -> Result<Bytes, T::Error>
where
    T: Body,
{
    futures_util::pin_mut!(body);

    // If there's only 1 chunk, we can just return Buf::to_bytes()
    let mut first = if let Some(buf) = body.data().await {
